import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = ''.join(data[1:1 + n])

    for length in range(1, n + 1):
        a_str = s[:length]
        if a_str[0] == '0':
            continue

        current = int(a_str)
        pos = length
        ok = True

        while pos < n:
            current += 1
            t = str(current)
            if not s.startswith(t, pos):
                ok = False
                break
            pos += len(t)

        if ok:
            sys.stdout.write(a_str)
            return

if __name__ == "__main__":
    main()
